{
  "bbb_prediction": "fail",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "In male Sprague Dawley rats, oral dosing of the closely related thienopyrimidine 7b produced minimal brain levels, directly demonstrating poor CNS access despite systemic exposure.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "The analogous aminopyrimidine-thienopyrimidine 12b gave a total brain AUC of only 104 ng·h/g after oral dosing in rats and was classified as poor penetration, closely matching the query's core and substituents.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C01"],
      "claim": "CLR457, a morpholine- and aminopyrimidine-containing kinase inhibitor, had a brain/plasma AUC ratio of 0.07, indicating minimal CNS penetration; this transfers to the query's morpholine/aminopyrimidine combination.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C04"],
      "claim": "In contrast, the morpholinopyrimidine radiotracer [18F]21 reached an initial brain SUV of 2.8 in rats and was judged brain penetrant, showing that this general scaffold can access brain when polar/efflux liabilities are reduced.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C03"],
      "claim": "[18F]FMN3PA, another morpholinopyrimidine, showed a brain/blood ratio of 0.5 and striatal uptake in rodents, indicating some permeability; however, its fast clearance and radiotracer context limit the weight against the direct PK failures.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is predicted to lack meaningful CNS access. The closest direct PK analogues (C07, C10, C01) all show minimal brain exposure or very low brain/plasma ratios, and the query's high TPSA/HBA and primary aminopyrimidine/morpholine motifs are associated with poor penetration and possible efflux. Occasional brain-penetrant PET analogues are less transferable because they lack the primary amine or are radiotracer/imaging contexts.",
  "evidence_gaps": [
    "No direct experimental brain or CSF exposure data are available for the query molecule.",
    "Efflux transporter susceptibility (P-gp/BCRP) of the query is not experimentally characterized.",
    "Most positive CNS evidence comes from PET radiotracer studies, which may not reflect sustained therapeutic brain concentrations.",
    "Species differences between rat, mouse, and human BBB/transporters could affect translation."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

